from abc import ABC, abstractmethod
from typing import Any, Protocol


class AbstractTranslator(ABC):
    """Abstract base class for translators.

    This interface allows both pandas and SQL translators to share a common
    protocol, decoupling them from internal details like ops/utils.py.
    """

    @abstractmethod
    def translate(self, expr, window: bool = True) -> Any:
        """Convert an expression tree into a target-specific representation."""
        pass

    @abstractmethod
    def shape_call(
        self,
        call: Any,
        window: bool = True,
        str_accessors: bool = False,
        verb_name: str | None = None,
        arg_name: str | None = None,
    ) -> Any:
        """Produce a dialect-specific call object."""
        pass


class HasTranslate(Protocol):
    """Protocol for objects that have a translate method."""

    def translate(self, expr, window: bool = True) -> Any:
        ...
